`,idt=`/**
 * TipOut · 销售额取值条件 · 订单小费状态判定
 *
 * 计算引擎汇总销售额 S 时：对每笔候选订单调用
 * matchOrderTipStatus(order, salesConditions.orderTipStatus)
 *
 * 含小费：卡小费或现金小费 > 0；加收服务费（Service Charge）不计为小费。
 * 未配置 / 空值：不过滤（向后兼容）。
 */
(function (root) {
  function num(v) {
    var n = Number(v);
    return isFinite(n) ? n : 0;
  }

  function hasPaidTip(order) {
    order = order || {};
    return num(order.cardTip) > 0 || num(order.cashTip) > 0;
  }

  /**
   * @param {object} order
   * @param {string|null|undefined} status - 'has_tip' | 'no_tip' | 空
   * @returns {boolean} 订单是否通过小费状态条件
   */
  function matchOrderTipStatus(order, status) {
    if (status == null || status === "") return true;
    if (status === "has_tip") return hasPaidTip(order);
    if (status === "no_tip") return !hasPaidTip(order);
    return true;
  }

  function filterOrdersByTipStatus(orders, status) {
    orders = orders || [];
    return orders.filter(function (o) {
      return matchOrderTipStatus(o, status);
    });
  }

  var api = {
    hasPaidTip: hasPaidTip,
    matchOrderTipStatus: matchOrderTipStatus,
    filterOrdersByTipStatus: filterOrdersByTipStatus,
  };
  if (typeof module !== "undefined" && module.exports) module.exports = api;
  root.TipOutOrderTipStatus = api;
})(typeof window !== "undefined" ? window : globalThis);
`,sdt=`/**
 * TipOut · 销售额/Tip Claim · 按支付方式分摊营业额类型金额
 *
 * S_order = R × (P_sel / P_all)；P 为含小费实付。
 * 未配置 selectedMethods：返回 R。
 * 计算引擎：对通过其它条件的订单调用本函数得到 S_order 再求和。
 */
(function (root) {
  var PAYMENT_METHOD_OPTIONS = [
    { value: "cash", labelZh: "现金", labelEn: "Cash" },
    { value: "credit_card", labelZh: "信用卡", labelEn: "Credit Card" },
    { value: "gift_card", labelZh: "礼品卡", labelEn: "Gift Card" },
    { value: "member_card", labelZh: "会员卡", labelEn: "Member Card" },
    { value: "alipay", labelZh: "ALIPAY", labelEn: "ALIPAY" },
    { value: "wechatpay", labelZh: "WECHATPAY", labelEn: "WECHATPAY" },
    { value: "doordash_d_pay", labelZh: "DOORDASH_D-PAY（自定义）", labelEn: "DOORDASH_D-PAY (Custom)" },
    { value: "uber_eats_d_pay", labelZh: "UBER_EATS_D-PAY（自定义）", labelEn: "UBER_EATS_D-PAY (Custom)" },
    { value: "coupon", labelZh: "券抵扣", labelEn: "Coupon" },
    { value: "points", labelZh: "积分抵扣", labelEn: "Points" },
  ];
  var KNOWN = {
    cash: 1,
    credit_card: 1,
    gift_card: 1,
    member_card: 1,
    alipay: 1,
    wechatpay: 1,
    doordash_d_pay: 1,
    uber_eats_d_pay: 1,
    coupon: 1,
    points: 1,
    // 兼容旧版落库值
    custom: 1,
    other: 1,
  };

  function num(v) {
    var n = Number(v);
    return isFinite(n) ? n : 0;
  }

  function roundMoney(x) {
    var n = Number(x);
    if (isNaN(n)) return 0;
    return Math.round(n * 100) / 100;
  }

  function isPaymentMethodValue(v) {
    return !!KNOWN[v];
  }

  function normalizeSelectedMethods(arr) {
    if (!Array.isArray(arr)) return [];
    var seen = {};
    var out = [];
    arr.forEach(function (v) {
      if (!KNOWN[v] || seen[v]) return;
      seen[v] = 1;
      out.push(v);
    });
    return out;
  }

  function sumTendersByMethods(tenders, methods) {
    var list = tenders || [];
    var filter = methods == null ? null : normalizeSelectedMethods(methods);
    var useFilter = filter && filter.length > 0;
    var sum = 0;
    list.forEach(function (t) {
      t = t || {};
      if (useFilter && filter.indexOf(t.method) < 0) return;
      sum += num(t.amount);
    });
    return sum;
  }

  /**
   * @param {{ revenueAmount: number, tenders?: Array<{method:string,amount:number}>, selectedMethods?: string[]|null }} input
   */
  function apportionRevenueByPaymentMethods(input) {
    input = input || {};
    var R = num(input.revenueAmount);
    var selected = normalizeSelectedMethods(input.selectedMethods);
    if (!selected.length) return roundMoney(R);

    var tenders = input.tenders || [];
    if (!tenders.length) return 0;

    var P_all = sumTendersByMethods(tenders, null);
    if (P_all <= 0) return 0;

    var P_sel = sumTendersByMethods(tenders, selected);
    if (P_sel <= 0) return 0;

    return roundMoney((R * P_sel) / P_all);
  }

  function formatPaymentMethodsLabelZh(methods) {
    var sel = normalizeSelectedMethods(methods);
    if (!sel.length) return "";
    var map = { other: "其他", custom: "自定义支付方式" };
    PAYMENT_METHOD_OPTIONS.forEach(function (o) {
      map[o.value] = o.labelZh;
    });
    return sel
      .map(function (v) {
        return map[v] || v;
      })
      .join("、");
  }

  var api = {
    PAYMENT_METHOD_OPTIONS: PAYMENT_METHOD_OPTIONS,
    isPaymentMethodValue: isPaymentMethodValue,
    normalizeSelectedMethods: normalizeSelectedMethods,
    roundMoney: roundMoney,
    sumTendersByMethods: sumTendersByMethods,
    apportionRevenueByPaymentMethods: apportionRevenueByPaymentMethods,
    formatPaymentMethodsLabelZh: formatPaymentMethodsLabelZh,
  };
  if (typeof module !== "undefined" && module.exports) module.exports = api;
  root.TipOutPaymentMethodApportion = api;
})(typeof window !== "undefined" ? window : globalThis);
`,ldt=`/* export.js — PDF / CSV / Email export */

function toggleExportMenu() {
  if (typeof validateSummaryDateRange === 'function' && !validateSummaryDateRange(true)) return;
  document.getElementById('exportMenu').classList.toggle('show');
}
document.addEventListener('click', function(e) {
  var menu = document.getElementById('exportMenu');
  if (menu && !e.target.closest('.export-dropdown')) {
    menu.classList.remove('show');
  }
});

function exportStoreLabel() {
  var storeSel = document.getElementById('storeSelect') || document.querySelector('.filter-bar select:nth-of-type(3)');
  return storeSel ? (storeSel.options[storeSel.selectedIndex] ? storeSel.options[storeSel.selectedIndex].text : storeSel.value || '') : '';
}

function collectDateTaskExportData() {
  var dailyRows = typeof getVisibleDailySummaryRows === 'function'
    ? getVisibleDailySummaryRows()
    : buildDailyDataset(getFilteredEmployees());
  var data = {
    kind: 'date',
    store: exportStoreLabel(),
    dateStart: document.getElementById('dateStart').value,
    dateEnd: document.getElementById('dateEnd').value,
    employees: [],
    dailySummaries: dailyRows.map(function(row) {
      return {
        date: row.dateKey,
        status: row.poolSummary.aggregateStatus,
        originalTips: row.poolSummary.originalTips,
        poolAmount: row.allocated ? row.poolSummary.poolAmount : null,
        allocatedAmount: row.poolSummary.allocatedAmount,
        unallocatedAmount: row.poolSummary.unallocatedAmount,
        poolCount: row.poolSummary.poolCount,
        pools: row.poolSummary.poolExecutions
      };
    })
  };
  var allocatedDates = typeof getAllocatedDates === 'function' ? getAllocatedDates() : new Set();
  var scopedEmployees = typeof getFilteredEmployees === 'function' ? getFilteredEmployees() : employees;
  scopedEmployees.forEach(function(emp) {
    var daily = [];
    dailyRows.forEach(function(row) { if (allocatedDates.has(row.dateKey)) daily.push(genDailyTip(emp, row.dateKey)); });
    if (daily.length === 0) return;
    var tb = daily.reduce(function(s, d) { return s + d.before; }, 0);
    var td = daily.reduce(function(s, d) { return s + (d.deducted || 0); }, 0);
    var tr = daily.reduce(function(s, d) { return s + (d.received || 0); }, 0);
    var tf = typeof calcTipAfter === 'function'
      ? calcTipAfter(tb, td, tr)
      : daily.reduce(function(s, d) { return s + d.after; }, 0);
    data.employees.push({
      name: emp.name, role: emp.role, daily: daily,
      totalBefore: tb, totalDeducted: td, totalReceived: tr, totalAfter: tf
    });
  });
  return data;
}

function collectEmployeeReconciliationExportData() {
  var aggregates = typeof getVisibleEmployeeSummaryAggregates === 'function'
    ? getVisibleEmployeeSummaryAggregates()
    : TipOutSummaryUi.aggregateEmployeeDailyDatasets(buildDailyDataset(getStoreEmployees()));
  return {
    kind: 'employee',
    store: exportStoreLabel(),
    dateStart: document.getElementById('dateStart').value,
    dateEnd: document.getElementById('dateEnd').value,
    employees: aggregates.map(function(aggregate) {
      return {
        employeeId: aggregate.employeeId,
        name: aggregate.name,
        role: (aggregate.roles || []).join(' / ') || aggregate.role,
        punchHours: aggregate.punchHoursDisplay,
        allocationHours: (aggregate.allocationHourSummaries || []).map(function(item) {
          var source = ({ 'original-punch': '原始打卡', 'pos-corrected': 'POS 修正', 'max-hours': '最大工时', manual: '手工录入', mixed: '混合来源', 'not-applicable': '不适用' })[item.source] || '原始打卡';
          return item.label + ': ' + (item.hoursValid ? item.hours + ' h' : '—') + '（' + source + '）';
        }).join('\\n') || '—',
        before: aggregate.before,
        deducted: aggregate.deducted,
        received: aggregate.received,
        netAdjustment: aggregate.netAdjustmentCents == null ? null : aggregate.netAdjustmentCents / 100,
        after: aggregate.after,
        status: aggregate.status,
        issueReasons: (aggregate.issueReasons || []).join('；')
      };
    })
  };
}

function collectCurrentSummaryExportData() {
  return activeSummaryView === 'employee'
    ? collectEmployeeReconciliationExportData()
    : collectDateTaskExportData();
}

function collectExportData() {
  return collectCurrentSummaryExportData();
}

function assertPaidExportSnapshotsAvailable() {
  if (!window.TipOutDateState) return true;
  var storeEl = document.getElementById('storeSelect');
  var store = storeEl ? storeEl.value : '';
  var dates = [];
  var detailDate = document.getElementById('detailDate');
  if (detailDate && detailDate.value) dates = [detailDate.value];
  else if (typeof getDateRange === 'function') dates = getDateRange();
  for (var i = 0; i < dates.length; i += 1) {
    var state = TipOutDateState.inspect(store, dates[i]);
    if (state.payoutStatus === 'error') throw new Error('发放快照不可用');
  }
  return true;
}

function exportAs(type) {
  if (typeof validateSummaryDateRange === 'function' && !validateSummaryDateRange(true)) return;
  document.getElementById('exportMenu').classList.remove('show');
  try { assertPaidExportSnapshotsAvailable(); }
  catch (error) { if (typeof showNotification === 'function') showNotification(error.message, 'error'); return; }
  var data = collectCurrentSummaryExportData();
  if (data.kind === 'employee' ? data.employees.length === 0 : data.dailySummaries.length === 0) { showNotification('没有可导出的数据', 'warning'); return; }
  if (type === 'pdf') exportPDF(data);
  else if (type === 'csv') exportCSV(data);
}

/* ─── CSV ─── */
function exportCSV(data) {
  if (data.kind === 'employee') {
    exportEmployeeReconciliationCSV(data);
    return;
  }
  showNotification('正在生成 CSV 文件...', 'info');
  var bom = '\\uFEFF';
  var lines = [];
  lines.push('Date Tip Allocation Summary');
  lines.push('"Store","' + data.store.replace(/"/g, '""') + '"');
  lines.push('"Date Range","' + data.dateStart + ' ~ ' + data.dateEnd + '"');
  lines.push('');
  lines.push('Date,Status,Original Tips($),Pool Amount($),Allocated($),Unallocated($),Pool Count');
  data.dailySummaries.forEach(function(day) {
    lines.push([day.date, day.status, day.originalTips.toFixed(2), day.poolAmount == null ? '' : day.poolAmount.toFixed(2), day.allocatedAmount == null ? '' : day.allocatedAmount.toFixed(2), day.unallocatedAmount == null ? '' : day.unallocatedAmount.toFixed(2), day.poolCount].map(csvCell).join(','));
  });
  lines.push('');
  lines.push('Date,Pool,Rule Summary,Status,Pool Amount($),Allocated($),Unallocated($)');
  data.dailySummaries.forEach(function(day) {
    day.pools.forEach(function(pool) {
      lines.push([day.date, pool.name, pool.ruleSummary, pool.status, pool.poolAmount.toFixed(2), pool.allocatedAmount == null ? '' : pool.allocatedAmount.toFixed(2), pool.unallocatedAmount == null ? '' : pool.unallocatedAmount.toFixed(2)].map(csvCell).join(','));
    });
  });

  var blob = new Blob([bom + lines.join('\\r\\n')], { type: 'text/csv;charset=utf-8;' });
  var url = URL.createObjectURL(blob);
  var a = document.createElement('a');
  a.href = url;
  a.download = 'DateTipAllocationSummary_' + data.dateStart + '_' + data.dateEnd + '.csv';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
  showNotification('CSV 导出成功', 'success');
}

function csvCell(value) {
  return '"' + String(value == null ? '' : value).replace(/"/g, '""') + '"';
}

function exportEmployeeReconciliationCSV(data) {
  showNotification('正在生成员工分配汇总 CSV 文件...', 'info');
  var lines = ['Employee Tip Allocation Summary'];
  lines.push(csvCell('Store') + ',' + csvCell(data.store));
  lines.push(csvCell('Date Range') + ',' + csvCell(data.dateStart + ' ~ ' + data.dateEnd));
  lines.push('');
  lines.push(['Employee', 'Role', 'Punch Hours', 'Allocation Hours', 'Original Tips($)', 'Deducted($)', 'Received($)', 'Net Adjustment($)', 'Final Amount($)', 'Issue Reasons'].map(csvCell).join(','));
  data.employees.forEach(function(employee) {
    lines.push([
      employee.name,
      employee.role,
      employee.punchHours,
      employee.allocationHours,
      employee.before == null ? '' : Number(employee.before).toFixed(2),
      employee.deducted == null ? '' : Number(employee.deducted).toFixed(2),
      employee.received == null ? '' : Number(employee.received).toFixed(2),
      employee.netAdjustment == null ? '' : Number(employee.netAdjustment).toFixed(2),
      employee.after == null ? '' : Number(employee.after).toFixed(2),
      employee.issueReasons
    ].map(csvCell).join(','));
  });
  var blob = new Blob(['\\uFEFF' + lines.join('\\r\\n')], { type: 'text/csv;charset=utf-8;' });
  var url = URL.createObjectURL(blob);
  var a = document.createElement('a');
  a.href = url;
  a.download = 'EmployeeTipAllocationSummary_' + data.dateStart + '_' + data.dateEnd + '.csv';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
  showNotification('员工分配汇总 CSV 导出成功', 'success');
}

/* ─── PDF: CDN loader ─── */
var _jspdfReady = false;

function loadJsPDFLib(callback) {
  if (_jspdfReady || window.jspdf) { _jspdfReady = true; callback(true); return; }
  var cdns = [
    ['https://cdn.jsdelivr.net/npm/jspdf@2.5.2/dist/jspdf.umd.min.js',
     'https://cdn.jsdelivr.net/npm/jspdf-autotable@3.8.4/dist/jspdf.plugin.autotable.min.js'],
    ['https://unpkg.com/jspdf@2.5.2/dist/jspdf.umd.min.js',
     'https://unpkg.com/jspdf-autotable@3.8.4/dist/jspdf.plugin.autotable.min.js'],
    ['https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.2/jspdf.umd.min.js',
     'https://cdnjs.cloudflare.com/ajax/libs/jspdf-autotable/3.8.4/jspdf.plugin.autotable.min.js']
  ];
  function tryLoad(idx) {
    if (idx >= cdns.length) { callback(false); return; }
    var s1 = document.createElement('script');
    s1.src = cdns[idx][0];
    var t1 = setTimeout(function() { s1.onload = s1.onerror = null; tryLoad(idx + 1); }, 8000);
    s1.onload = function() {
      clearTimeout(t1);
      var s2 = document.createElement('script');
      s2.src = cdns[idx][1];
      var t2 = setTimeout(function() { s2.onload = s2.onerror = null; tryLoad(idx + 1); }, 8000);
      s2.onload = function() {
        clearTimeout(t2);
        if (window.jspdf) { _jspdfReady = true; callback(true); }
        else tryLoad(idx + 1);
      };
      s2.onerror = function() { clearTimeout(t2); tryLoad(idx + 1); };
      document.head.appendChild(s2);
    };
    s1.onerror = function() { clearTimeout(t1); tryLoad(idx + 1); };
    document.head.appendChild(s1);
  }
  tryLoad(0);
}

/* ─── PDF: entry ─── */
function exportPDF(data) {
  showNotification('正在加载 PDF 组件...', 'info');
  loadJsPDFLib(function(loaded) {
    if (loaded) {
      if (data.kind === 'employee') generateEmployeeReconciliationJsPDF(data);
      else generateJsPDF(data);
    } else {
      if (data.kind === 'employee') printEmployeeReconciliationAsPDF(data);
      else printAsPDF(data);
    }
  });
}

/* ─── PDF: print fallback ─── */
function printAsPDF(data) {
  if (data.dailySummaries) { printDatePoolAsPDF(data); return; }
  showNotification('正在生成 PDF 预览页面...', 'info');
  var gb = 0, gd = 0, gr = 0, gf = 0;

  var win = window.open('', '_blank');
  if (!win) { showNotification('弹窗被浏览器拦截，请允许弹窗后重试', 'error'); return; }

  var doc = win.document;
  doc.open();
  doc.write('<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Tip Distribution Report</title>');
  doc.write('<style>');
  doc.write('*{margin:0;padding:0;box-sizing:border-box}');
  doc.write('body{font-family:Arial,Helvetica,sans-serif;padding:30px 40px;color:#222;font-size:12px}');
  doc.write('h1{font-size:20px;font-weight:700;margin-bottom:6px}');
  doc.write('.meta{font-size:12px;color:#666;margin-bottom:3px}');
  doc.write('hr{border:none;border-top:1px solid #ddd;margin:14px 0}');
  doc.write('table{width:100%;border-collapse:collapse;margin-top:10px}');
  doc.write('th{background:#1677ff;color:#fff;padding:7px 10px;text-align:left;font-size:11px}');
  doc.write('td{padding:5px 10px;border-bottom:1px solid #eee;font-size:11px}');
  doc.write('.r{text-align:right}');
  doc.write('.sub td{font-weight:700;background:#ebf0fa}');
  doc.write('.gt td{font-weight:700;background:#1677ff;color:#fff}');
  doc.write('@media print{body{padding:15px 20px}@page{size:landscape;margin:10mm}}');
  doc.write('.hint{text-align:center;padding:16px;color:#888;font-size:13px;margin-top:20px}');
  doc.write('.hint b{color:#1677ff}');
  doc.write('</style></head><body>');

  doc.write('<h1>Tip Distribution Report</h1>');
  doc.write('<div class="meta">Store: ' + escH(data.store) + '</div>');
  doc.write('<div class="meta">Date Range: ' + data.dateStart + ' ~ ' + data.dateEnd + '</div>');
  doc.write('<div class="meta">Generated: ' + new Date().toLocaleString() + '</div>');
  doc.write('<hr>');
  doc.write('<table><thead><tr><th>Employee</th><th>Role</th><th>Date</th>');
  doc.write('<th class="r">Tips Before</th><th class="r">Deducted</th><th class="r">Received</th><th class="r">Tips After</th>');
  doc.write('</tr></thead><tbody>');

  data.employees.forEach(function(emp) {
    emp.daily.forEach(function(d) {
      doc.write('<tr><td>' + escH(emp.name) + '</td><td>' + escH(emp.role) + '</td><td>' + d.date + '</td>');
      doc.write('<td class="r">$' + d.before.toFixed(2) + '</td>');
      doc.write('<td class="r">$' + (d.deducted || 0).toFixed(2) + '</td>');
      doc.write('<td class="r">$' + (d.received || 0).toFixed(2) + '</td>');
      doc.write('<td class="r">$' + d.after.toFixed(2) + '</td></tr>');
    });
    doc.write('<tr class="sub"><td>' + escH(emp.name) + ' Subtotal</td><td></td><td></td>');
    doc.write('<td class="r">$' + emp.totalBefore.toFixed(2) + '</td>');
    doc.write('<td class="r">$' + emp.totalDeducted.toFixed(2) + '</td>');
    doc.write('<td class="r">$' + emp.totalReceived.toFixed(2) + '</td>');
    doc.write('<td class="r">$' + emp.totalAfter.toFixed(2) + '</td></tr>');
    gb += emp.totalBefore; gd += emp.totalDeducted; gr += emp.totalReceived; gf += emp.totalAfter;
  });

  doc.write('<tr class="gt"><td>Grand Total</td><td></td><td></td>');
  doc.write('<td class="r">$' + gb.toFixed(2) + '</td>');
  doc.write('<td class="r">$' + gd.toFixed(2) + '</td>');
  doc.write('<td class="r">$' + gr.toFixed(2) + '</td>');
  doc.write('<td class="r">$' + gf.toFixed(2) + '</td></tr>');
  doc.write('</tbody></table>');
  doc.write('<div class="hint">Please press <b>Ctrl + P</b>, then select <b>"Save as PDF"</b> to download.</div>');
  doc.write('</body></html>');
  doc.close();

  setTimeout(function() { win.print(); }, 500);
  showNotification('PDF 预览已打开，请在弹出窗口中保存为 PDF', 'success');
}

